add_filter( 'woocommerce_checkout_fields', 'perfectpixel_numeric_postcode', 9999 );
add_action( 'woocommerce_after_checkout_form', 'perfectpixel_numeric_postcode_script' );

function perfectpixel_numeric_postcode( $fields ) {
	foreach ( array( 'billing', 'shipping' ) as $group ) {
		$key = $group . '_postcode';
		if ( isset( $fields[ $group ][ $key ] ) ) {
			$fields[ $group ][ $key ]['custom_attributes']['inputmode'] = 'numeric';
			$fields[ $group ][ $key ]['custom_attributes']['pattern']   = '[0-9]*';
		}
	}
	return $fields;
}

function perfectpixel_numeric_postcode_script() {
	?>
	<script>
	document.addEventListener( 'input', function ( e ) {
		if ( e.target && ( e.target.id === 'billing_postcode' || e.target.id === 'shipping_postcode' ) ) {
			var clean = e.target.value.replace( /\D/g, '' );
			if ( clean !== e.target.value ) {
				e.target.value = clean;
			}
		}
	} );
	</script>
	<?php
}
